import java.util.*;

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int r = 0, c = matrix[0].length - 1;   // top-right corner
        while (r < matrix.length && c >= 0) {
            int v = matrix[r][c];
            if (v == target) return true;
            if (v > target) c--;   // whole column below is even bigger
            else r++;              // whole row to the left is even smaller
        }
        return false;
    }
}

