function searchMatrix(matrix, target) {
  for (const row of matrix) {
    let lo = 0, hi = row.length - 1;
    while (lo <= hi) { const m = (lo + hi) >> 1; if (row[m] === target) return true; if (row[m] < target) lo = m + 1; else hi = m - 1; }
  }
  return false;
}
